bun -e '
for (const id of ["remediation-quality-gate-scripts","remediation-remove-config-drift","remediation-tsconfig-strict"]) {
  const raw = await Bun.file(`.aidd/features/${id}/feature.json`).text();
  const j = JSON.parse(raw);
  console.log("=====", id, "=====");
  console.log("status:", JSON.stringify(j.status), "| keys:", Object.keys(j).join(","));
  console.log("spec typeof:", typeof j.spec, "| contains real newline:", j.spec.includes("\n"), "| contains literal backslash-n:", j.spec.includes("\\n"));
  console.log("spec value first 120 chars:", JSON.stringify(j.spec.slice(0,120)));
}'

bun run /dev/stdin <<'EOF'
const raw = await Bun.file(".aidd/features/remediation-tsconfig-strict/feature.json").text();
const j = JSON.parse(raw);
const s = j.spec;
// find first occurrence of the separator region between item 1 and 2
const idx = s.indexOf("true");
const around = s.slice(idx, idx+8);
console.log("chars around first 'true':", [...around].map(c => c.charCodeAt(0)).join(","), "->", JSON.stringify(around));
console.log("has backslash char (92):", [...s].some(c=>c.charCodeAt(0)===92));
console.log("has newline (10):", s.includes(String.fromCharCode(10)));
EOF
